d.","status":"approved","clip_id":"084d6071-d274-52b3-8f24-62b731a741cb","author_id":"94c18071-e354-43e5-9596-5ab65eb6d106","created_at":"2026-11-06T08:32:59.477786+00:00","approved_at":"2026-11-06T08:34:52.66125+00:00"},{"id":"c55d3de5-3543-5723-8cab-8adcd047e788","body":"Fun idea for a quick style comparison.","status":"approved","clip_id":"51628a69-1010-5201-b5bc-20346473161f","author_id":"ceb6b030-1b86-49c7-af0d-09fc2db576d8","created_at":"2026-11-06T08:33:09.693908+00:00","approved_at":"2026-11-06T08:34:52.66125+00:00"},{"id":"c8e8a2df-3dcb-5ca9-9d31-239a2afe504d","body":"Erangel always makes me want to queue for another match.","status":"approved","clip_id":"86916319-1668-569a-8fd0-8ff991d483c4","author_id":"aa182005-e481-4df2-a56f-09ee60da7f5b","created_at":"2026-11-06T08:32:53.009455+00:00","approved_at":"2026-11-06T08:34:52.66125+00:00"},{"id":"ce5c4d44-18de-5872-ac8e-3c92d93cbdfd","body":"Who would you challenge to a race?","status":"approved","clip_id":"0266cd87-d7a3-53a6-8a08-6f454c48a6a5","author_id":"ceb6b030-1b86-49c7-af0d-09fc2db576d8","created_at":"2026-11-06T08:33:13.266913+00:00","approved_at":"2026-11-06T08:34:52.66125+00:00"},{"id":"fe97c24a-2ac8-5b44-b609-7f03a46101bf","body":"More short clips from this creator would be fun.","status":"approved","clip_id":"3f6877fa-0e13-59d4-8316-afafba965d25","author_id":"aa182005-e481-4df2-a56f-09ee60da7f5b","created_at":"2026-11-06T08:33:12.363475+00:00","approved_at":"2026-11-06T08:34:52.66125+00:00"}]}$comments$::jsonb as v;
create temporary table reviewed_comments on commit drop as select * from jsonb_to_recordset((select v->'comments' from comment_payload))
 as e(id uuid,clip_id uuid,author_id uuid,body text);
select c.id from private.clip_comments c join reviewed_comments e using(id) for update of c;
do $guard$ begin
 if (select count(*) from reviewed_comments)<>40 or (select count(distinct id) from reviewed_comments)<>40 then raise exception 'wrong_comment_scope';end if;
 if (select count(*) from public.video_posts p where p.status='approved')<>10
 or (select count(*) from public.video_posts p where to_jsonb(p) in(select value from jsonb_array_elements((select v->'posts' from comment_payload))))<>10
 then raise exception 'homepage_changed';end if;
 if (select count(*) from private.clip_comments c where to_jsonb(c) in(select value from jsonb_array_elements((select v->'original_comments' from comment_payload))))<>20
 then raise exception 'existing_comments_changed';end if;
 if (select count(*) from private.clip_comments c join reviewed_comments e using(id)
  join private.accounts a on a.user_id=c.author_id where c.clip_id=e.clip_id and c.author_id=e.author_id and c.body=e.body
  and c.status in('pending','approved') and a.cohort='development' and a.state='active')<>40
 then raise exception 'exact_normal_comment_submissions_required';end if;
end $guard$;
update private.clip_comments c set status='approved',approved_at=statement_timestamp() from reviewed_comments e where c.id=e.id and c.status='pending';
do $final$ begin
 if (select count(*) from private.clip_comments c join reviewed_comments e using(id) where c.status='approved' and c.approved_at is not null)<>40
 then raise exception 'comment_approval_failed';end if;
end $final$;
commit;
select jsonb_build_object('approved_fixture_comments',count(*),'clips',count(distinct clip_id)) as approved from private.clip_comments
